// SaveCaptureMetadata is the resolver for the saveCaptureMetadata field.
func (r *mutationResolver) SaveCaptureMetadata(ctx context.Context, input graphql1.SaveCaptureMetadataInput) (*graphql1.MediaPayload, error) {
	tenantID, responsibilityID, err := r.externalResponsibility(ctx)
	if err != nil {
		return nil, err
	}
	mediaID, err := identity.ParseID(input.MediaID)
	if err != nil {
		return nil, invalidID("mediaId")
	}
	bootstrapRaw, err := r.Bus.Ask(ctx, capturebootstrap.Query{TenantID: tenantID, ResponsibilityID: responsibilityID})
	if err != nil {
		return nil, err
	}
	bootstrap := bootstrapRaw.(capturecore.Bootstrap)
	var policyDoc struct {
		GPSRequired                       bool    `json:"gpsRequired"`
		AllowGallery                      bool    `json:"allowGallery"`
		GeofenceMeters                    float64 `json:"geofenceMeters"`
		AssetLatitudeE6, AssetLongitudeE6 *int32
	}
	_ = json.Unmarshal(bootstrap.Draft.PolicyPayload, &policyDoc)
	var lat, lon *float64
	if policyDoc.AssetLatitudeE6 != nil && policyDoc.AssetLongitudeE6 != nil {
		a, b := float64(*policyDoc.AssetLatitudeE6)/1e6, float64(*policyDoc.AssetLongitudeE6)/1e6
		lat, lon = &a, &b
	}
	metadata := capturecore.MetadataInput{TenantID: tenantID, ResponsibilityID: responsibilityID, MediaID: mediaID, RequirementKey: input.RequirementKey, Description: input.Description, CaptureSource: input.CaptureSource, DeviceContext: input.DeviceContext, Policy: capturecore.GPSPolicy{Required: policyDoc.GPSRequired, AllowGallery: policyDoc.AllowGallery, AssetLatitude: lat, AssetLongitude: lon, GeofenceMeters: policyDoc.GeofenceMeters}}
	if input.Gps != nil {
		captured, _ := time.Parse(time.RFC3339, input.Gps.CapturedAt)
		started, _ := time.Parse(time.RFC3339, input.Gps.WindowStartedAt)
		metadata.CapturedAt, metadata.WindowStartedAt = captured, started
		metadata.Latitude, metadata.Longitude, metadata.AccuracyMeters = &input.Gps.Latitude, &input.Gps.Longitude, &input.Gps.AccuracyMeters
	}
	raw, err := r.Bus.Send(ctx, capturesave.Command{Input: metadata})
	if err != nil {
		return nil, err
	}
	media := raw.(database.MediaObject)
	return &graphql1.MediaPayload{Media: mapMedia(media), UserErrors: []*graphql1.UserError{}, ClientMutationID: input.ClientMutationID}, nil
}

