// Memberships is the resolver for the memberships field.
func (r *queryResolver) Memberships(ctx context.Context, first *int, after *string) (*graphql1.MembershipConnection, error) {
	meta, ok := requestctx.FromContext(ctx)
	if !ok {
		return nil, unauthenticated()
	}
	if err := internalRole(meta, auth.TenantAdmin, auth.Manager); err != nil {
		return nil, err
	}
	limit := intValue(first)
	if limit <= 0 || limit > 100 {
		limit = 25
	}
	var rows []database.Membership
	err := (tenanttx.Runner{DB: r.DB}).Within(ctx, meta.TenantID, func(tx *gorm.DB) error {
		query := tx.Where("tenant_id = ?", meta.TenantID)
		if after != nil && *after != "" {
			cursor, parseErr := identity.ParseID(*after)
			if parseErr != nil {
				return invalidID("after")
			}
			query = query.Where("id > ?", cursor)
		}
		return query.Order("id ASC").Limit(limit + 1).Find(&rows).Error
	})
	if err != nil {
		return nil, err
	}
	hasNext := len(rows) > limit
	if hasNext {
		rows = rows[:limit]
	}
	nodes := make([]*graphql1.Membership, 0, len(rows))
	for _, row := range rows {
		mapped, mapErr := mapMembership(ctx, r.DB, row)
		if mapErr != nil {
			return nil, mapErr
		}
		nodes = append(nodes, mapped)
	}
	end := ""
	if len(rows) > 0 {
		end = rows[len(rows)-1].ID.String()
	}
	return &graphql1.MembershipConnection{Nodes: nodes, PageInfo: pageInfo(end, hasNext)}, nil
}

